import { useEffect, useRef } from 'react';
import { submissionsApi } from '@/api/submissions';

export function useSubmissionGeoBackfill(enabled: boolean) {
  const startedRef = useRef(false);

  useEffect(() => {
    if (!enabled || startedRef.current) {
      return;
    }

    startedRef.current = true;
    let cancelled = false;

    const kickoff = async () => {
      const state = await submissionsApi.geoBackfillState();
      if (cancelled) {
        return;
      }

      if (state.completed || state.status !== 'idle' || state.scheduled) {
        return;
      }

      await submissionsApi.geoBackfillTick();
    };

    kickoff().catch(() => {
      // Cron 调度是主路径；设置页 kickoff 失败不应阻塞后台 UI。
    });

    return () => {
      cancelled = true;
      startedRef.current = false;
    };
  }, [enabled]);
}
