import { apiClient } from './client';

export interface SubmissionItem {
  id: number;
  date: string;
  title: string;
  form: string;
  payload: Record<string, any>;
  context: Record<string, any>;
  source_url?: string;
  ip?: string;
  country?: string;
  region?: string;
  city?: string;
  location?: string;
}

export interface SubmissionsListResponse {
  items: SubmissionItem[];
  total: number;
  total_pages: number;
  per_page: number;
  paged: number;
}

export interface GeoBackfillStateResponse {
  status: 'idle' | 'running' | 'paused' | 'completed' | 'busy';
  completed: boolean;
  upper_bound_id: number;
  next_before_id: number;
  scheduled: boolean;
  scheduled_at: number;
  retry_after: number;
  scanned: number;
  updated: number;
  skipped: number;
  unresolved: number;
  live_lookups: number;
  cache_hits: number;
  updated_total: number;
  skipped_total: number;
  unresolved_total: number;
  live_lookup_total: number;
  cache_hit_total: number;
  scanned_total: number;
  last_run_at: string;
  completed_at: string;
}

export type GeoBackfillTickResponse = GeoBackfillStateResponse;

const REGEX_TRAILING_SLASH = /\/$/;

export const submissionsApi = {
  list: (params?: { per_page?: number; paged?: number }) =>
    apiClient.get<SubmissionsListResponse>('/submissions', params),
  geoBackfillState: () =>
    apiClient.get<GeoBackfillStateResponse>('/submissions/geo-backfill/state'),
  geoBackfillTick: () =>
    apiClient.post<GeoBackfillTickResponse>('/submissions/geo-backfill/tick'),
  delete: (id: number) =>
    apiClient.delete<{ id: number }>(`/submissions/${id}`),
  exportCsv: async () => {
    const base = (
      (window as any).zeroyEditor?.apiUrl ||
      (window as any).zeroySettings?.apiUrl ||
      (window as any).zeroyAdmin?.apiUrl ||
      '/wp-json/zeroy/v1'
    ).replace(REGEX_TRAILING_SLASH, '');
    const nonce =
      (window as any).zeroyEditor?.nonce ||
      (window as any).zeroySettings?.nonce ||
      (window as any).zeroyAdmin?.nonce ||
      '';
    const url = `${base}/submissions/export`;
    const res = await fetch(url, {
      method: 'GET',
      headers: {
        'X-WP-Nonce': nonce,
        Accept: 'text/csv',
      },
      credentials: 'same-origin',
    });
    if (!res.ok) {
      throw new Error('导出失败');
    }
    const blob = await res.blob();
    const a = document.createElement('a');
    const objectUrl = URL.createObjectURL(blob);
    a.href = objectUrl;
    a.download = `zeroy-submissions-${new Date()
      .toISOString()
      .replace(/[:.]/g, '-')}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(objectUrl);
  },
};
