import React, { useEffect, useState } from 'react';
import { RemoteNotificationsContainer } from '@/components/remote-notifications';
import { useTokenValidation } from '@/hooks/use-token-validation';
import { TokenSetup } from './components/ai-settings/token-setup';
import { LoadingSpinner } from './components/common/loading-spinner';
import { RewriteErrorNotice } from './components/common/rewrite-error-notice';
import { type TabId, TabNavigation } from './components/common/tab-navigation';
import { useSubmissionGeoBackfill } from './hooks/use-submission-geo-backfill';

/**
 * 页面布局包装组件
 */
const PageWrapper: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="zeroy-admin-app min-h-screen bg-gray-50">
    <div className="mx-auto max-w-6xl p-8">{children}</div>
  </div>
);

/**
 * Rewrite 错误页面包装组件
 */
const RewriteErrorPage: React.FC = () => (
  <PageWrapper>
    <div className="mb-6">
      <h1 className="font-semibold text-2xl text-gray-900">zeroY 管理</h1>
    </div>
    <RewriteErrorNotice />
  </PageWrapper>
);

const TemplatesTab = React.lazy(() =>
  import('./components/templates/templates-list').then((m) => ({
    default: m.TemplatesList,
  }))
);

const AiSettingsTab = React.lazy(() =>
  import('./components/ai-settings/ai-settings-tab').then((m) => ({
    default: m.AiSettingsTab,
  }))
);

const PerformanceTab = React.lazy(() =>
  import('./components/performance/performance-tab').then((m) => ({
    default: m.PerformanceTab,
  }))
);

const DesignTab = React.lazy(() =>
  import('./components/design/design-tab').then((m) => ({
    default: m.DesignTab,
  }))
);

const SubmissionsTab = React.lazy(() =>
  import('./components/submissions/submissions-tab').then((m) => ({
    default: m.SubmissionsTab,
  }))
);

// Tab 组件映射
const TAB_COMPONENTS: Record<TabId, React.LazyExoticComponent<React.FC>> = {
  templates: TemplatesTab,
  'ai-settings': AiSettingsTab,
  performance: PerformanceTab,
  design: DesignTab,
  submissions: SubmissionsTab,
};

// 解析URL片段到选项卡ID
const parseUrlFragment = (): TabId => {
  const hash = window.location.hash.slice(1); // 移除 # 符号
  const validTabs: TabId[] = [
    'templates',
    'ai-settings',
    'performance',
    'design',
    'submissions',
  ];

  if (validTabs.includes(hash as TabId)) {
    return hash as TabId;
  }

  return 'templates'; // 默认选项卡
};

// 更新URL片段
const updateUrlFragment = (tabId: TabId) => {
  const newUrl = `${window.location.pathname}${window.location.search}#${tabId}`;
  window.history.replaceState(null, '', newUrl);
};

export const SettingsApp: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabId>(() => parseUrlFragment());
  const [isTokenValidated, setIsTokenValidated] = useState(false);

  const {
    hasToken,
    isLoading,
    hasChecked,
    isValidating,
    tokenValidationState,
    isRewriteError,
  } = useTokenValidation();

  useSubmissionGeoBackfill(!(isLoading || isRewriteError));

  // 初始化时读取URL片段
  useEffect(() => {
    const initialTab = parseUrlFragment();
    setActiveTab(initialTab);
  }, []);

  // 处理选项卡切换
  const handleTabChange = (tabId: TabId) => {
    setActiveTab(tabId);
    updateUrlFragment(tabId);
  };

  // 处理token验证成功
  const handleTokenValidated = () => {
    setIsTokenValidated(true);
  };

  // 如果检测到 REST API rewrite 配置错误，显示错误提示
  if (isRewriteError) {
    return <RewriteErrorPage />;
  }

  // 如果正在加载设置或正在验证token，显示加载状态
  if (isLoading || (hasToken && isValidating && !hasChecked)) {
    const message = isValidating ? '验证 Token 中...' : '加载设置中...';
    return (
      <PageWrapper>
        <LoadingSpinner message={message} />
      </PageWrapper>
    );
  }

  // 决定是否需要显示认证界面
  const needsAuthentication =
    !hasToken || (hasChecked && tokenValidationState.status === 'error');

  // 如果需要认证且没有手动验证成功，显示token设置界面
  if (needsAuthentication && !isTokenValidated) {
    return (
      <PageWrapper>
        <TokenSetup onTokenValidated={handleTokenValidated} />
      </PageWrapper>
    );
  }

  // 显示完整的设置界面
  return (
    <PageWrapper>
      {/* 远程通知 */}
      <RemoteNotificationsContainer className="mb-6" maxDisplay={3} />

      <div className="mb-8">
        <div className="mb-6 flex items-center gap-2">
          <h1 className="font-semibold text-2xl text-gray-900">zeroY 管理</h1>
          {(window as any).zeroyConfig?.version && (
            <span className="rounded-full bg-gray-100 px-2 font-medium text-gray-600 text-sm">
              {(window as any).zeroyConfig.version}
            </span>
          )}
        </div>

        <TabNavigation activeTab={activeTab} onTabChange={handleTabChange} />
      </div>

      {/* 内容区域 */}
      <div className="mt-8">
        <React.Suspense fallback={<LoadingSpinner />}>
          {React.createElement(TAB_COMPONENTS[activeTab])}
        </React.Suspense>
      </div>
    </PageWrapper>
  );
};
