import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import type React from 'react';
import { useState } from 'react';
import { settingsApi } from '@/api/settings';
import { useNotification } from '@/components/notification';

interface TokenSetupProps {
  onTokenValidated: () => void;
}

export const TokenSetup: React.FC<TokenSetupProps> = ({ onTokenValidated }) => {
  const { notify } = useNotification();
  const queryClient = useQueryClient();
  const [localTokenData, setLocalTokenData] = useState<{
    api_token: string;
  } | null>(null);
  const [tokenVerificationStatus, setTokenVerificationStatus] = useState<{
    status: 'idle' | 'verifying' | 'success' | 'error';
    message: string;
  }>({ status: 'idle', message: '' });

  // 获取设置数据
  const { data, isLoading } = useQuery({
    queryKey: ['settings'],
    queryFn: settingsApi.get,
  });

  // 使用本地数据或从服务器获取的数据
  const settings = data?.settings;
  const currentToken = localTokenData?.api_token ?? settings?.api_token ?? '';

  const saveTokenMutation = useMutation({
    mutationFn: settingsApi.update,
    onSuccess: (_response) => {
      notify('success', 'API Token 已保存');
      // Optimistically update global bootstrap to avoid refresh/race conditions
      try {
        const w: any = window as any;
        if (w.zeroySettings) {
          w.zeroySettings.settings = {
            ...(w.zeroySettings.settings || {}),
            api_token: currentToken,
          };
        }
      } catch {
        // Ignore
      }
      queryClient.invalidateQueries({ queryKey: ['settings'] });
      setLocalTokenData(null);
      onTokenValidated();
    },
    onError: () => {
      notify('error', 'Token 保存失败，请重试');
    },
  });

  const verifyTokenMutation = useMutation({
    mutationFn: settingsApi.verifyToken,
    onSuccess: (result) => {
      setTokenVerificationStatus({
        status: result.valid ? 'success' : 'error',
        message: result.message,
      });
      if (result.valid) {
        // 验证成功后保存token
        if (!settings) {
          notify('error', '无法获取设置数据');
          return;
        }
        const newSettings = {
          ...settings,
          api_token: currentToken,
        };
        saveTokenMutation.mutate(newSettings);
      } else {
        notify('error', result.message);
      }
    },
    onError: () => {
      const errorMessage = 'Token 验证失败，请检查网络连接';
      setTokenVerificationStatus({
        status: 'error',
        message: errorMessage,
      });
      notify('error', errorMessage);
    },
  });

  const handleTokenVerify = () => {
    if (!currentToken.trim()) {
      notify('error', '请先输入 API Token');
      return;
    }
    setTokenVerificationStatus({ status: 'verifying', message: '验证中...' });
    verifyTokenMutation.mutate(currentToken);
  };

  const handleTokenChange = (value: string) => {
    setLocalTokenData({ api_token: value });
    setTokenVerificationStatus({ status: 'idle', message: '' });
  };

  const hasToken = currentToken.trim();

  if (isLoading) {
    return (
      <div className="mx-auto max-w-2xl">
        <div className="rounded-xl border border-gray-200 bg-white p-8 shadow-sm">
          <div className="text-center">
            <div className="text-gray-500">加载中...</div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-2xl">
      <div className="rounded-xl border border-gray-200 bg-white p-8 shadow-sm">
        {/* 标题 */}
        <div className="mb-8 text-center">
          <h1 className="mb-4 font-bold text-3xl text-gray-900">
            欢迎使用 zeroY
          </h1>
          <p className="text-gray-600">
            要开始使用 zeroY 的强大功能，请先配置您的 API Token
          </p>
        </div>

        {/* Token 输入 */}
        <div className="space-y-6">
          <div>
            <label
              className="mb-3 block font-medium text-gray-700"
              htmlFor="api-token"
            >
              API Token
            </label>
            <div className="flex space-x-3">
              <input
                className="flex-1 rounded-lg border border-gray-300 px-4 py-3 font-mono text-sm transition-colors focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                id="api-token"
                onChange={(e) => handleTokenChange(e.target.value)}
                placeholder="输入您的 API Token"
                type="password"
                value={currentToken}
              />
              <button
                className={`rounded-lg px-6 py-3 font-medium text-sm transition-colors ${
                  hasToken && tokenVerificationStatus.status !== 'verifying'
                    ? 'bg-blue-600 text-white hover:bg-blue-700'
                    : 'cursor-not-allowed bg-gray-100 text-gray-400'
                }`}
                disabled={
                  !hasToken || tokenVerificationStatus.status === 'verifying'
                }
                onClick={handleTokenVerify}
                type="button"
              >
                {tokenVerificationStatus.status === 'verifying' ? (
                  <div className="flex items-center space-x-2">
                    <div className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
                    <span>验证中</span>
                  </div>
                ) : (
                  '验证并继续'
                )}
              </button>
            </div>

            {/* Token 验证状态 */}
            {tokenVerificationStatus.status !== 'idle' && (
              <div
                className={`mt-3 flex items-center space-x-2 text-sm ${
                  tokenVerificationStatus.status === 'success'
                    ? 'text-green-600'
                    : 'text-red-600'
                }`}
              >
                {tokenVerificationStatus.status === 'success' ? (
                  <svg
                    className="h-4 w-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <title>Success</title>
                    <path
                      d="M5 13l4 4L19 7"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                    />
                  </svg>
                ) : (
                  <svg
                    className="h-4 w-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <title>Error</title>
                    <path
                      d="M6 18L18 6M6 6l12 12"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                    />
                  </svg>
                )}
                <span>{tokenVerificationStatus.message}</span>
              </div>
            )}

            <div className="mt-3 space-y-2 text-gray-600 text-sm">
              <p>
                <strong>什么是 API Token？</strong>
              </p>
              <p>
                API Token 是您的 zeroy 服务认证凭证，用于验证您的身份并访问 AI
                功能。
              </p>
              <p>
                如果您还没有 Token，请前往{' '}
                <a
                  className="text-blue-600 hover:text-blue-800"
                  href="https://www.zeroy.app"
                  rel="noopener noreferrer"
                  target="_blank"
                >
                  zeroY 官网
                </a>{' '}
                注册获取。
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
