import type React from 'react';

interface RewriteErrorNoticeProps {
  className?: string;
}

type ServerType = 'apache' | 'nginx' | 'litespeed' | 'iis' | 'unknown';

/**
 * 检测服务器类型
 */
function detectServerType(): { type: ServerType; raw: string } {
  const raw =
    (window as any).zeroySettings?.serverSoftware ||
    (window as any).zeroyEditor?.serverSoftware ||
    '';
  const lower = raw.toLowerCase();

  if (lower.includes('apache')) {
    return { type: 'apache', raw };
  }
  if (lower.includes('nginx')) {
    return { type: 'nginx', raw };
  }
  if (lower.includes('litespeed')) {
    return { type: 'litespeed', raw };
  }
  if (lower.includes('iis') || lower.includes('microsoft')) {
    return { type: 'iis', raw };
  }
  return { type: 'unknown', raw };
}

