import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useCallback, useEffect, useState } from 'react';
import { RestApiRewriteError } from '@/api/client';
import { settingsApi } from '@/api/settings';
import { useNotification } from '@/components/notification';

interface TokenValidationState {
  status: 'idle' | 'verifying' | 'success' | 'error';
  message: string;
}

interface UseTokenValidationReturn {
  // Token状态
  hasToken: boolean;
  isTokenValid: boolean;
  tokenValidationState: TokenValidationState;
  isValidating: boolean; // 是否正在验证中
  hasChecked: boolean; // 是否已经完成初始检查

  // 验证方法
  verifyToken: (token: string) => void;
  resetValidation: () => void;

  // 设置数据
  settings: any;
  isLoading: boolean;

  // 错误状态
  isRewriteError: boolean; // 是否是 REST API rewrite 配置错误
  settingsError: Error | null; // 获取设置时的错误

  // 更新设置
  updateSettings: (settings: any) => void;
}

export const useTokenValidation = (): UseTokenValidationReturn => {
  const { notify } = useNotification();
  const queryClient = useQueryClient();
  const [tokenValidationState, setTokenValidationState] =
    useState<TokenValidationState>({
      status: 'idle',
      message: '',
    });
  const [hasChecked, setHasChecked] = useState(false);

  // 获取设置
  const {
    data: settingsData,
    isLoading,
    error: settingsError,
  } = useQuery({
    queryKey: ['settings'],
    queryFn: settingsApi.get,
    retry: (failureCount, error) => {
      // 如果是 rewrite 错误，不要重试
      if (error instanceof RestApiRewriteError) {
        return false;
      }
      // 其他错误最多重试 2 次
      return failureCount < 2;
    },
  });

  // 检测是否是 REST API rewrite 配置错误
  const isRewriteError = settingsError instanceof RestApiRewriteError;

  const settings = settingsData?.settings;
  const hasToken = Boolean(settings?.api_token?.trim());
  const isTokenValid = tokenValidationState.status === 'success';
  const isValidating = tokenValidationState.status === 'verifying';

  // ----- 本地缓存：降低激活码验证频次 -----
  const href = typeof window !== 'undefined' ? window.location.href : '';
  const isDevLike = href.includes('dev=1') || href.includes('dev=2');
  const CACHE_SUCCESS_TTL_MS = isDevLike ? 5 * 60 * 1000 : 12 * 60 * 60 * 1000; // 成功缓存：开发/预发5分钟，生产12小时
  const CACHE_FAIL_TTL_MS = 1 * 60 * 60 * 1000; // 失败退避：1小时
  const AUTO_VERIFY_DISABLED =
    (window as any)?.zeroySettings?.disableTokenAutoVerify === true;

  const tokenHash = (() => {
    const token = settings?.api_token || '';
    // 非加密hash，避免明文token写入localStorage
    let h = 0;
    for (let i = 0; i < token.length; i++) {
      // biome-ignore lint/nursery/noBitwiseOperators: Hash calculation requires bitwise operations
      h = (h << 5) - h + token.charCodeAt(i);
      // biome-ignore lint/nursery/noBitwiseOperators: Ensures 32-bit integer
      h |= 0;
    }
    return `h${h}`;
  })();

  const cacheKey = `zeroy_token_verify_cache_${tokenHash}`;
  type CacheRecord = {
    status: 'success' | 'error';
    message: string;
    ts: number;
  };

  // biome-ignore lint/correctness/useExhaustiveDependencies: Constants are stable
  const readCache = useCallback((): CacheRecord | null => {
    try {
      const raw = localStorage.getItem(cacheKey);
      if (!raw) {
        return null;
      }
      const parsed = JSON.parse(raw) as CacheRecord;
      if (!(parsed?.status && parsed.ts)) {
        return null;
      }
      const now = Date.now();
      const ttl =
        parsed.status === 'success' ? CACHE_SUCCESS_TTL_MS : CACHE_FAIL_TTL_MS;
      if (now - parsed.ts < ttl) {
        return parsed;
      }
      return null;
    } catch {
      return null;
    }
  }, [cacheKey]);

  const writeCache = (rec: CacheRecord) => {
    try {
      localStorage.setItem(cacheKey, JSON.stringify(rec));
    } catch {
      // ignore quota errors
    }
  };

  // Token验证
  const verifyTokenMutation = useMutation({
    mutationFn: settingsApi.verifyToken,
    onSuccess: (data) => {
      setTokenValidationState({
        status: data.valid ? 'success' : 'error',
        message: data.message,
      });
      setHasChecked(true);

      // 写入缓存（成功/失败分别按不同TTL退避）
      writeCache({
        status: data.valid ? ('success' as const) : ('error' as const),
        message: data.message,
        ts: Date.now(),
      });

      // 只在手动验证时显示通知，初始自动验证不显示
      if (hasChecked) {
        notify(data.valid ? 'success' : 'error', data.message);
      }
    },
    onError: () => {
      const errorMessage = 'Token 验证失败，请检查网络连接';
      setTokenValidationState({
        status: 'error',
        message: errorMessage,
      });
      setHasChecked(true);

      // 失败退避缓存
      writeCache({ status: 'error', message: errorMessage, ts: Date.now() });

      // 只在手动验证时显示通知
      if (hasChecked) {
        notify('error', errorMessage);
      }
    },
  });

  // 更新设置
  const updateSettingsMutation = useMutation({
    mutationFn: settingsApi.update,
    onSuccess: (response) => {
      notify('success', response.message);
      // Keep global bootstrap in sync for immediate consumers
      try {
        const w: any = window as any;
        if (w.zeroySettings) {
          w.zeroySettings.settings =
            response.settings || w.zeroySettings.settings;
        }
      } catch {
        // Ignore
      }
      queryClient.invalidateQueries({ queryKey: ['settings'] });
    },
    onError: () => {
      notify('error', '保存失败，请重试');
    },
  });

  // 当设置加载完成且有token时，自动验证（带缓存/退避）
  useEffect(() => {
    if (
      isLoading ||
      !hasToken ||
      hasChecked ||
      tokenValidationState.status !== 'idle'
    ) {
      return;
    }

    // 可选：完全禁用自动验证，只在手动点击时验证
    if (AUTO_VERIFY_DISABLED) {
      setHasChecked(true);
      return;
    }

    // 命中缓存则直接使用缓存结果，跳过网络请求
    const cached = readCache();
    if (cached) {
      setTokenValidationState({
        status: cached.status,
        message: cached.message,
      });
      setHasChecked(true);
      return;
    }

    setTokenValidationState({
      status: 'verifying',
      message: '正在验证 Token...',
    });
    verifyTokenMutation.mutate(settings?.api_token || '');
  }, [
    isLoading,
    hasToken,
    hasChecked,
    settings?.api_token,
    tokenValidationState.status,
    verifyTokenMutation.mutate,
    AUTO_VERIFY_DISABLED,
    readCache,
  ]);

  const verifyToken = (token: string) => {
    if (!token?.trim()) {
      notify('error', '请先输入 API Token');
      return;
    }
    setTokenValidationState({ status: 'verifying', message: '验证中...' });
    verifyTokenMutation.mutate(token);
  };

  const resetValidation = () => {
    setTokenValidationState({ status: 'idle', message: '' });
  };

  const updateSettings = (newSettings: any) => {
    updateSettingsMutation.mutate(newSettings);
  };

  return {
    hasToken,
    isTokenValid,
    tokenValidationState,
    isValidating,
    hasChecked,
    verifyToken,
    resetValidation,
    settings,
    isLoading,
    isRewriteError,
    settingsError: settingsError as Error | null,
    updateSettings,
  };
};
